CREATE OR REPLACE FUNCTION current_time_off_profile(target_organization_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT profile.id FROM profiles profile JOIN memberships membership ON membership.profile_id = profile.id WHERE profile.auth_user_id = auth.uid() AND profile.status = 'active' AND membership.organization_id = target_organization_id AND membership.status = 'active' LIMIT 1 $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION submit_leave_request(target_organization_id uuid, start_date date, end_date date, leave_type leave_type, reason text, retry_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE actor uuid; employee employees%ROWTYPE; request leave_requests%ROWTYPE; now_at timestamptz := transaction_timestamp(); BEGIN actor := current_time_off_profile(target_organization_id); IF actor IS NULL THEN RAISE EXCEPTION 'TIME_OFF_FORBIDDEN'; END IF; SELECT * INTO employee FROM employees WHERE organization_id = target_organization_id AND profile_id = actor FOR UPDATE; IF employee.id IS NULL OR employee.status <> 'active' THEN RAISE EXCEPTION 'TIME_OFF_FORBIDDEN'; END IF; IF start_date < (now_at AT TIME ZONE (SELECT timezone FROM organizations WHERE id = target_organization_id))::date OR end_date < start_date OR end_date - start_date + 1 > 366 THEN RAISE EXCEPTION 'TIME_OFF_INVALID_DATE_RANGE'; END IF; IF start_date < employee.hire_date OR (employee.termination_date IS NOT NULL AND end_date >= employee.termination_date) THEN RAISE EXCEPTION 'TIME_OFF_OUTSIDE_EMPLOYMENT'; END IF; INSERT INTO leave_requests (organization_id, employee_id, start_date, end_date, leave_type, reason, status, submitted_at, version) VALUES (target_organization_id, employee.id, start_date, end_date, leave_type, NULLIF(btrim(reason), ''), 'submitted', now_at, 1) RETURNING * INTO request; INSERT INTO leave_request_events (organization_id, leave_request_id, request_version, action, actor_profile_id, actor_role, organization_timezone, prior_status, resulting_status) SELECT target_organization_id, request.id, 1, 'submitted', actor, membership.role::text, organization.timezone, NULL, 'submitted' FROM memberships membership JOIN organizations organization ON organization.id = target_organization_id WHERE membership.profile_id = actor AND membership.organization_id = target_organization_id; RETURN jsonb_build_object('id', request.id, 'status', request.status, 'version', request.version, 'submittedAt', request.submitted_at); EXCEPTION WHEN exclusion_violation THEN RAISE EXCEPTION 'TIME_OFF_OVERLAP'; END; $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION transition_leave_request(target_organization_id uuid, target_request_id uuid, expected_version integer, action text, decision_note text DEFAULT NULL, fallback_reason text DEFAULT NULL, retry_request_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE actor uuid; request leave_requests%ROWTYPE; actor_role text; next_status leave_status; now_at timestamptz := transaction_timestamp(); BEGIN actor := current_time_off_profile(target_organization_id); IF actor IS NULL THEN RAISE EXCEPTION 'TIME_OFF_FORBIDDEN'; END IF; SELECT request.* INTO request FROM leave_requests request WHERE request.id = target_request_id AND request.organization_id = target_organization_id FOR UPDATE; IF request.id IS NULL THEN RAISE EXCEPTION 'TIME_OFF_UNAVAILABLE'; END IF; SELECT membership.role::text INTO actor_role FROM memberships membership WHERE membership.organization_id = target_organization_id AND membership.profile_id = actor AND membership.status = 'active'; IF action = 'cancel' THEN next_status := 'cancelled'; ELSIF action = 'approve' THEN next_status := 'approved'; ELSE next_status := 'declined'; END IF; IF request.version <> expected_version THEN RAISE EXCEPTION 'TIME_OFF_STALE_VERSION'; END IF; IF request.status <> 'submitted' THEN RAISE EXCEPTION 'TIME_OFF_INVALID_STATE'; END IF; IF action = 'cancel' AND request.employee_id <> (SELECT id FROM employees WHERE profile_id = actor AND organization_id = target_organization_id) THEN RAISE EXCEPTION 'TIME_OFF_FORBIDDEN'; END IF; IF action <> 'cancel' AND actor_role NOT IN ('manager', 'administrator') THEN RAISE EXCEPTION 'TIME_OFF_FORBIDDEN'; END IF; IF action = 'decline' AND char_length(btrim(decision_note)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'TIME_OFF_INVALID_NOTE'; END IF; UPDATE leave_requests SET status = next_status, version = version + 1, reviewer_profile_id = CASE WHEN action <> 'cancel' THEN actor ELSE reviewer_profile_id END, decision_at = CASE WHEN action <> 'cancel' THEN now_at ELSE decision_at END, cancelled_at = CASE WHEN action = 'cancel' THEN now_at ELSE cancelled_at END, updated_at = now_at WHERE id = request.id; INSERT INTO leave_request_events (organization_id, leave_request_id, request_version, action, actor_profile_id, actor_role, organization_timezone, was_late, prior_status, resulting_status, decision_note, fallback_reason) SELECT target_organization_id, request.id, expected_version + 1, action::leave_event_action, actor, actor_role, organization.timezone, ((now_at AT TIME ZONE organization.timezone)::date > request.start_date), request.status, next_status, NULLIF(btrim(decision_note), ''), NULLIF(btrim(fallback_reason), '') FROM organizations organization WHERE organization.id = target_organization_id; RETURN jsonb_build_object('id', request.id, 'status', next_status, 'version', expected_version + 1, 'eventTime', now_at); END; $$;--> statement-breakpoint
