CREATE OR REPLACE FUNCTION cancel_leave_request(target_organization_id uuid, target_request_id uuid, expected_version integer, retry_request_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT transition_leave_request(target_organization_id, target_request_id, expected_version, 'cancel', NULL, NULL, retry_request_id) $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION approve_leave_request(target_organization_id uuid, target_request_id uuid, expected_version integer, fallback_reason text, retry_request_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT transition_leave_request(target_organization_id, target_request_id, expected_version, 'approve', NULL, fallback_reason, retry_request_id) $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION decline_leave_request(target_organization_id uuid, target_request_id uuid, expected_version integer, decision_note text, fallback_reason text, retry_request_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT transition_leave_request(target_organization_id, target_request_id, expected_version, 'decline', decision_note, fallback_reason, retry_request_id) $$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION get_leave_request_detail(target_organization_id uuid, target_request_id uuid) RETURNS SETOF jsonb LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT jsonb_build_object('request', to_jsonb(request), 'events', COALESCE((SELECT jsonb_agg(to_jsonb(event) ORDER BY event.occurred_at, event.id) FROM leave_request_events event WHERE event.leave_request_id = request.id), '[]'::jsonb)) FROM leave_requests request WHERE request.id = target_request_id AND request.organization_id = target_organization_id AND request.status <> 'draft' $$;--> statement-breakpoint
